    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead: if the remaining space is close to the next item, prioritize this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for the next item: massive reward
            score -= (100.0 - (post_residual - next_item_size) as f64) * 2.5;
        } else {
            // Cannot fit next item: slight penalty to discourage stranding this bin
            score += 15.0;
        }
    }

    // 3. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // If we have other options, strongly discourage opening a new bin
            score += 120.0;
        } else {
            // Forced to open a new bin
            score = 0.0;
        }
    }

    // 4. Mean residual balancing: avoid creating bins that are outliers compared to current average
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression scaling: as we near the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Prefer filling existing bins that are already "tight"
    if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base objective: Best-Fit (minimize post_residual).
    // Penalize gaps that are too small to fit common items (10-30 range).
    let gap_penalty = if post < 20.0 && post > 0.0 {
        (20.0 - post).powi(2) * 1.5
    } else {
        0.0
    };

    // Lookahead: If next_item_size is large, favor bins with more remaining space.
    let lookahead_penalty = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post < needed {
            (needed - post) * 2.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Global state optimization: 
    // As stream progresses, penalize opening new bins unless necessary (fitting_bins_count == 0).
    let new_bin_penalty = if res == cap {
        (open_bins_count as f64 * 5.0) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Balance mean_residual: avoid outliers by preferring bins close to the current mean.
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // Combine heuristics:
    // We want the lowest score, so we add positive penalties.
    post + gap_penalty + lookahead_penalty + new_bin_penalty + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as we approach the end of the stream
    // to encourage filling existing bins.
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress).powf(0.5) * 40.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate "Tightness": favor post_residuals that are either 0 (perfect fit)
    // or large enough to accommodate the lookahead item.
    let post = post_residual as f64;
    let tightness_score = if post == 0.0 {
        -25.0 // Strong reward for perfect fills
    } else if next_item_size > 0 && post >= next_item_size as f64 {
        -10.0 // Reward for leaving room for the next item
    } else {
        post.powf(1.2) // Penalize small, unusable gaps
    };

    // Factor in the state of other bins: if we have many bins with low residuals,
    // we want to prioritize closing them or filling them efficiently.
    let global_efficiency = (mean_residual - post) * (open_bins_count as f64 / 10.0);

    // If this is the only bin that fits the item, reward it significantly to avoid
    // unnecessary new bin openings.
    let necessity_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    tightness_score + new_bin_penalty + global_efficiency + necessity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_sq = post_res * post_res;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = res_sq;

    // Penalty for creating a "fragmented" bin: if post_residual is small but > 0, 
    // it's often worse than leaving it empty (if we have many bins) or filling it perfectly.
    // We penalize small residuals that are unlikely to accommodate the next_item_size.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 10.0;
    }

    // Dynamic pressure: as the stream progresses, favor packing tighter to minimize new bin openings.
    // If we are near the end, the cost of opening a new bin is high, so minimize post_residual strictly.
    let tightness_factor = 1.0 + (progress * 5.0);
    score *= tightness_factor;

    // If this is the only bin that can fit the item, heavily prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // New bin candidate logic: bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are extremely sparse (high mean_residual).
        // This prevents opening new bins unless necessary.
        score = 200.0 + (mean_residual * 2.0) - (progress * 50.0);
    }

    score
}

