pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep bins tight.
    // Penalty for creating a gap that is too small for common items (e.g., < 15).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // highly reward this bin (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further reward if it fills the bin nearly perfectly.
        if (post_residual - next_item_size) < 5 {
            score -= 30.0;
        }
    }

    // 3. Global State Awareness: If we are nearing the end of the stream, 
    // prioritize packing tighter to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Fitting Constraint: If this is the last bin that can fit the item, 
    // reduce the penalty for a poor fit to ensure we don't open a new bin unnecessarily.
