        // If the item fits perfectly in an existing bin, discourage new bin creation.
        if fitting_bins_count > 0 {
            score += 60.0;
        }

        // If the item is large, it's often better to start a new bin than to 
        // leave a small gap in an existing one.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": If post_residual is small (1..9), it is likely unusable for future items.
    // We add a heavy penalty for creating small gaps that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If the next item is large, prioritize keeping space available.
    // If post_residual is less than the next item, we penalize the bin usage.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, discourage adding to it if it creates
    // a very tight fit while other bins have more room (mean_residual).
    if bin_residual < bin_capacity {
        if post_residual < 5 {
            score += 15.0;
        }
        // Penalize filling bins if there are many open bins already to encourage consolidation.
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. New bin management: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only do this if fitting_bins_count is low or if current bins are already very full.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can take the item.
            score += 60.0;
        }
        // As the stream progresses, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // 5. Reward perfect fits: If the item fills the bin exactly, prioritize it.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}
